        for turn in history.suffix(4).reversed() where turn.role != .tool {
            addTerms(from: turn.content)
        }

        let expanded = ([base] + added).filter { !$0.isEmpty }.joined(separator: " ")
        return .init(query: bounded(expanded), addedTerms: added)
