    private static func shouldForceFinalSchemaAfterObservation(
        availableTools: [ToolDefinition],
        stepIndex: Int,
        hasObservations: Bool
    ) -> Bool {
        guard stepIndex > 0,
              hasObservations,
              availableTools.count == 1,
              let onlyTool = availableTools.first else {
            return false
        }
        // Once the only available no-argument tool has returned a trusted
        // observation, another action can only repeat the same invocation.
        // Keep the second turn model-backed while constraining it to the one
        // remaining valid decision: synthesize a final response.
        return !onlyTool.requiresApproval && onlyTool.capabilityContract.arguments.isEmpty
    }

    static func shouldForceActionSchema(
        request: AgentKernelRequest,
        availableTools: [ToolDefinition],
        stepIndex: Int,
        hasObservations: Bool
    ) -> Bool {
        guard stepIndex == 0, !hasObservations, !availableTools.isEmpty else { return false }
        let routing = IntentRouter.classify(sanitizedStructuredUserMessage(request.userMessage))
        return IntentRouter.intentRequiresTool(routing) && !routing.requiresClarification
    }

    static func structuredToolSourceIDs(
        secureIDs: Set<String>,
        optionIDs: Set<String>,
        routingIDs: Set<String>
    ) -> Set<String> {
        let secure = Set(secureIDs.map(ToolRouteGuard.canonicalToolID))
        let scoped = structuredRequestedToolSourceIDs(optionIDs: optionIDs, routingIDs: routingIDs)
        if scoped.isEmpty, optionIDs.isEmpty, routingIDs.isEmpty {
            return secure
        }
        return scoped.intersection(secure)
    }

    static func structuredRequestedToolSourceIDs(
        optionIDs: Set<String>,
        routingIDs: Set<String>
    ) -> Set<String> {
        let options = Set(optionIDs.map(ToolRouteGuard.canonicalToolID))
        let routing = Set(routingIDs.map(ToolRouteGuard.canonicalToolID))
        if !options.isEmpty, !routing.isEmpty {
            let intersection = options.intersection(routing)
            return intersection.isEmpty ? options : intersection
        } else if !options.isEmpty {
            return options
        } else if !routing.isEmpty {
            return routing
        } else {
            return []
        }
    }

