        var lines: [String] = []
        var used = 0
        for item in recent {
            let role: String
            switch item.role {
            case .user: role = "User"
            case .assistant: role = "Assistant"
            case .system: role = "System"
            case .tool: role = "Tool"
            }
            let content = sanitizeHistoryContent(item.content)
