        let frames = stride(from: 0, to: 12, by: 1).map { step -> UIImage in
            let phase = CGFloat(step) / 11
            let pulse = 0.12 + sin(phase * .pi) * 0.22
            let glow = 0.38 + sin(phase * .pi) * 0.42
