        guard let value = value as? String else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private static func sourceRevision(_ value: Any?) -> String? {
        guard let revision = normalizedString(value),
              revision.lowercased() != "unknown",
              !revision.hasPrefix("$(") else {
            return nil
        }
        return revision
    }

    private static func workingTreeDigest(_ value: Any?) -> String? {
        guard let digest = normalizedString(value)?.lowercased(),
              digest.count == 64,
              digest.unicodeScalars.allSatisfy({
                  CharacterSet(charactersIn: "0123456789abcdef").contains($0)
              }) else {
            return nil
        }
        return digest
    }

    private static func normalizedBool(_ value: Any?) -> Bool? {
        if let value = value as? Bool {
            return value
        }
        guard let value = normalizedString(value)?.lowercased() else {
            return nil
        }
        switch value {
        case "true", "1", "yes":
            return true
        case "false", "0", "no":
            return false
        default:
            return nil
        }
    }

    static func physicalExecutionEnvironment(
