        let digest = HMAC<SHA256>.authenticationCode(
            for: Data("\(domain)|\(value.uuidString)".utf8),
            using: key
        )
        var bytes = Array(digest.prefix(16))
        bytes[6] = (bytes[6] & 0x0f) | 0x40
        bytes[8] = (bytes[8] & 0x3f) | 0x80
