    private static func discoverRanges(in chars: [Character]) -> Result<[(Int, Int)], AgentTurnParseError> {
        var ranges: [(Int, Int)] = []
        var depth = 0
        var start: Int?
        var inString = false
        var escape = false
        var i = 0

        while i < chars.count {
            let ch = chars[i]
            if inString {
                if escape {
                    if !isValidEscape(at: i, in: chars) {
                        return .failure(.malformedEscapeSequence)
                    }
                    if ch == "u" { i += 4 }
                    escape = false
                } else if ch == "\\" {
                    escape = true
                } else if ch == "\"" {
                    inString = false
                }
                i += 1
                continue
            }

            if ch == "\"", depth > 0 {
                inString = true
            } else if ch == "{" {
                if depth == 0 { start = i }
                depth += 1
            } else if ch == "}" {
                guard depth > 0 else {
                    i += 1
                    continue
                }
                depth -= 1
                if depth == 0, let s = start {
                    ranges.append((s, i))
                    start = nil
                }
            }
            i += 1
        }

        if inString || depth != 0 { return .failure(.incompleteJSON) }
        return .success(ranges)
    }

    private static func parseJSONObject(chars: [Character], range: (Int, Int)) -> Result<[String: Any], AgentTurnParseError> {
