    private static func isValidEscape(at index: Int, in chars: [Character]) -> Bool {
        let esc = chars[index]
        switch esc {
        case "\"", "\\", "/", "b", "f", "n", "r", "t":
            return true
        case "u":
            guard index + 4 < chars.count else { return false }
            for j in (index + 1)...(index + 4) {
                if chars[j].hexDigitValue == nil { return false }
            }
            return true
        default:
            return false
        }
    }

    private static func validateEscapes(in chars: [Character]) -> Bool {
        var inString = false
        var escape = false
        var i = 0

        while i < chars.count {
            let ch = chars[i]
            if inString {
                if escape {
                    if !isValidEscape(at: i, in: chars) { return false }
                    if ch == "u" { i += 4 }
                    escape = false
                } else if ch == "\\" {
                    escape = true
                } else if ch == "\"" {
                    inString = false
                }
                i += 1
                continue
            }

            if ch == "\"" {
                inString = true
            }
            i += 1
        }

        return true
    }
