    private nonisolated static func nextRequiredMemoryAction(
        memoryPlan: MemoryCommandPlan?,
        steps: [AgentStep],
        availableToolIDs: Set<String>
    ) -> AgentAction? {
        guard let memoryPlan else { return nil }
        let actionToolIDs = steps
            .filter { $0.kind == .action }
            .compactMap(\.toolID)
