                    && !lower.hasPrefix("web search results:")
                    && !lower.hasPrefix("http")
                    && !lower.contains("<lumen_web_payload")
                    && !lower.contains("\"mediakind\"")
                    && !webFinalRequiresObservationFallback(line)
