    private static func fetchedChunksByPersistentIDResult(context: ModelContext) -> (chunksByID: [PersistentIdentifier: RAGChunk], diagnostic: String?) {
        let chunks: [RAGChunk]
        do {
            let stagingPrefix = RAGChunk.replacementStagingSourceTypePrefix
