          + CommunicationLocalTool.all
          + LocationMediaHealthLocalTool.all
          + KnowledgeLocalTool.all
    }

    init(tools: [any LocalTool]? = nil) {
        var map: [ToolID: any LocalTool] = [:]
        var duplicates: [ToolID] = []
        for tool in tools ?? Self.defaultTools {
