                RoundedRectangle(cornerRadius: 10, style: .continuous)
                    .strokeBorder(Theme.border, lineWidth: 1)
            }
        }
    }

    private func stepCountLabel(_ visibleCount: Int) -> String {
        let base = "\(visibleCount) reasoning step\(visibleCount == 1 ? "" : "s")"
