            if case .failed(let failure) = outcome {
                conversationPersistenceError = failure.userMessage
            } else {
                conversationPersistenceError = "The new conversation could not be saved."
            }
            return
        }
        if let seedPrompt {
            pendingDrafts[convo.id] = seedPrompt
