private struct TriggerMutationSnapshot {
    let title: String
    let prompt: String
    let scheduleType: String
    let fireDate: Date?
    let timeOfDayMinutes: Int?
    let intervalSeconds: TimeInterval?
    let beforeNextEventMinutes: Int?
    let isPaused: Bool
    let nextFireAt: Date?

