import XCTest
@testable import Lumen

final class ContextQueryRewriterTests: XCTestCase {
    func testAddsRecentHistoryTermsWithoutRepeatingUserTerms() {
        let result = ContextQueryRewriter.rewrite(
            userInput: "what about that adapter?",
