def _global_tokenizer_snapshot_stability_signatures(
    snapshot_dir: Path,
) -> dict[str, tuple[int, ...]]:
    signatures = {
        ".": _file_stability_signature(
            os.stat(snapshot_dir, follow_symlinks=False)
        )
    }
    for filename in GLOBAL_TOKENIZER_SNAPSHOT_FILES:
