    lowered = slot_id.lower()
    wanted: set[str] = set()
    for candidate in all_slot_ids:
        candidate_lower = candidate.lower()
        if candidate == slot_id:
            continue
        if any(token in lowered for token in ["router", "cortex", "intent", "planner"]):
            wanted.add(candidate)
