def _invalid_variant(tool_id: str) -> str:
    parts = tool_id.split(".")
    if len(parts) == 1:
        return tool_id + ".run"
    last = parts[-1]
    replacement = {
        "search": "browse",
        "create": "add",
        "draft": "compose",
        "send": "deliver",
        "open": "launch",
    }.get(last, last + "2")
    return ".".join([*parts[:-1], replacement])

