def _canonical_strict_json_object(
    value: str,
    *,
    sort_keys: bool = False,
) -> str | None:
    try:
        payload = _strict_json_loads(value)
    except (
        json.JSONDecodeError,
        _DuplicateJSONKeyError,
        _NonFiniteJSONNumberError,
    ):
        return None
    if not isinstance(payload, dict):
        return None
    return json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=sort_keys,
        separators=(",", ":"),
    )


def _fleet_requested_slot_id(
    manifest: AgentBehaviorManifest,
    user: str,
) -> str | None:
    text = user.casefold()
    matches: list[str] = []
    for slot in manifest.fleet.slots:
        aliases = {
            slot.id.casefold(),
            slot.role.casefold(),
            _normalize_agent_role(slot.id).casefold(),
            _normalize_agent_role(slot.role).casefold(),
        }
        if any(
            alias
            and re.search(
                rf"(?<![a-z0-9_.-]){re.escape(alias)}(?![a-z0-9_.-])",
                text,
            )
            for alias in aliases
        ):
            matches.append(slot.id)
    unique_matches = sorted(set(matches))
    return unique_matches[0] if len(unique_matches) == 1 else None


