def _manifest_valid_executor_payload(
    manifest: AgentBehaviorManifest,
    assistant: str,
) -> dict[str, Any] | None:
    try:
        payload = _strict_json_loads(assistant)
    except (
        json.JSONDecodeError,
        _DuplicateJSONKeyError,
        _NonFiniteJSONNumberError,
    ):
        return None
