def _token_windows(value: str, size: int) -> set[tuple[str, ...]]:
    tokens = value.split()
    if len(tokens) < size:
        return set()
    return {
        tuple(tokens[index:index + size])
        for index in range(len(tokens) - size + 1)
    }


