def _stable_split_records(records: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    if not records:
        return [], []
    ranked = sorted(records, key=lambda record: str(record.get("id") or ""))
    val_count = 1 if len(ranked) > 1 else 0
    if len(ranked) >= 10:
        val_count = max(1, round(len(ranked) * 0.15))
    val_ids = {str(record.get("id") or "") for record in ranked[:val_count]}
    train: list[dict[str, Any]] = []
    val: list[dict[str, Any]] = []
    for record in records:
        cloned = {**record}
        cloned["split"] = "validation" if str(record.get("id") or "") in val_ids else "train"
        if cloned["split"] == "validation":
            val.append(cloned)
        else:
            train.append(cloned)
    return train, val


def _write_jsonl(path: Path, records: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    artifact_mode = _artifact_mode(path)
    descriptor, temporary_name = tempfile.mkstemp(
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
    )
    temporary_path = Path(temporary_name)
    try:
        os.fchmod(descriptor, artifact_mode)
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = -1
            for record in records:
                line = json.dumps(record, ensure_ascii=False, sort_keys=True) + "\n"
                handle.write(line.encode("utf-8"))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_path, path)
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        temporary_path.unlink(missing_ok=True)


def _artifact_mode(path: Path) -> int:
    try:
        current_mode = path.lstat().st_mode
    except FileNotFoundError:
        return _DEFAULT_ARTIFACT_MODE
    if not stat.S_ISREG(current_mode):
        return _DEFAULT_ARTIFACT_MODE
    return stat.S_IMODE(current_mode)

