    @staticmethod
    def _extract_array_literals(block: str, label: str) -> list[str]:
        match = re.search(rf"\b{re.escape(label)}\s*:\s*\[", block)
        if not match:
            match = re.search(rf"\b{re.escape(label)}\s*=\s*\[", block)
        if not match:
            return []
        start = match.end() - 1
        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(block)):
            char = block[index]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            else:
                if char == '"':
                    in_string = True
                elif char == "[":
                    depth += 1
                elif char == "]":
                    depth -= 1
                    if depth == 0:
                        return string_literals(block[start:index + 1])
        return []

