            else str(message.get("content") or ""),
        }
        if isinstance(message, dict)
        else {"role": "unknown", "content": str(message)}
        for message in messages
    ]
    return json.dumps(canonical, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


